const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Cambodia boundaries and split into North/South
  const cambodiaBounds = ee.Geometry.Polygon([
    [[102.3, 10.0], [107.6, 10.0], [107.6, 14.7], [102.3, 14.7], [102.3, 10.0]]
  ]);

  const northernCambodia = ee.Geometry.Polygon([
    [[102.3, 12.5], [107.6, 12.5], [107.6, 14.7], [102.3, 14.7], [102.3, 12.5]]
  ]);

  const southernCambodia = ee.Geometry.Polygon([
    [[102.3, 10.0], [107.6, 10.0], [107.6, 12.5], [102.3, 12.5], [102.3, 10.0]]
  ]);

  // 2. Load MODIS fire detection data
  const startDate = '2016-08-01';
  const endDate = '2018-02-28';

  const fireCollection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(startDate, endDate)
    .select('FireMask');

  const collectionSize = fireCollection.size().getInfo();
  console.log(`MODIS Fire images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('C1');
    return;
  }

  // 3. Count fire detections (FireMask >= 7 indicates fire detected with confidence)
  const fireDetections = fireCollection.map(function(img) {
    return img.gte(7).rename('fire_count');
  });

  // 4. Calculate fire counts for northern region
  const northFireCount = fireDetections
    .map(function(img) {
      return img.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: northernCambodia,
        scale: 1000,
        maxPixels: 1e9
      }).get('fire_count');
    })
    .filter(ee.Filter.neq('fire_count', null));

  const northTotal = northFireCount.aggregate_sum('fire_count').getInfo();
  console.log(`Northern Cambodia fire detections: ${northTotal}`);

  // 5. Calculate fire counts for southern region
  const southFireCount = fireDetections
    .map(function(img) {
      return img.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: southernCambodia,
        scale: 1000,
        maxPixels: 1e9
      }).get('fire_count');
    })
    .filter(ee.Filter.neq('fire_count', null));

  const southTotal = southFireCount.aggregate_sum('fire_count').getInfo();
  console.log(`Southern Cambodia fire detections: ${southTotal}`);

  // 6. Validation and answer
  if (northTotal === null || southTotal === null || isNaN(northTotal) || isNaN(southTotal)) {
    console.log('C3');
    return;
  }

  if (northTotal === 0 && southTotal === 0) {
    console.log(`No fire detections found in either region`);
    console.log('B');
    return;
  }

  console.log(`Comparison: North=${northTotal}, South=${southTotal}`);

  if (northTotal > southTotal) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
